def render_prompt(prompt_id, **vars_):
    p = PROMPTS[prompt_id]
    return [{"role": "system", "content": p["system"]},
            {"role": "user", "content": Template(p["user"]).safe_substitute(**{k: str(v) for k, v in vars_.items()})}]


